package com.enterprise.oms.testsupport;

import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

/**
 * Base class for tests that need a real PostgreSQL 16 (Testcontainers). Skipped automatically (not failed) when
 * Docker is not available ({@code disabledWithoutDocker = true}). Container credentials are generated by
 * Testcontainers at runtime. Use together with {@code @SpringBootTest}; the datasource properties are overridden
 * dynamically, and the service's own Flyway migrations (plus {@code classpath:db/common}) run against Postgres.
 */
@Testcontainers(disabledWithoutDocker = true)
public abstract class AbstractPostgresIT {

    @Container
    protected static final PostgreSQLContainer<?> POSTGRES = new PostgreSQLContainer<>("postgres:16-alpine");

    @DynamicPropertySource
    static void postgresProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", POSTGRES::getJdbcUrl);
        registry.add("spring.datasource.username", POSTGRES::getUsername);
        registry.add("spring.datasource.password", POSTGRES::getPassword);
        registry.add("spring.datasource.driver-class-name", POSTGRES::getDriverClassName);
        JwtTestTokens.registerProperties(registry);
    }
}
